  gorsel: `<table class="tablo"><tr><th>Resort</th><th>Lift ticket</th><th>Distance to town</th><th>Slopes</th></tr><tr><td>Pine Peak</td><td>600 TL</td><td>12 km</td><td>5</td></tr><tr><td>White Hill</td><td>450 TL</td><td>25 km</td><td>8</td></tr></table>`,
